    <section class="pricing-faq"><header><p class="kicker">\u8865\u5145\u8BF4\u660E</p><h2>\u540E\u7EED\u670D\u52A1\u8BF4\u660E</h2></header><div><details><summary>\u5982\u679C\u7B2C\u4E8C\u5E74\u4E0D\u7EED\u8D39\uFF0C\u4F1A\u53D1\u751F\u4EC0\u4E48\uFF1F</summary><div><p><strong>\u5373\u4F7F\u7B2C\u4E8C\u5E74\u6CA1\u6709\u8D2D\u4E70\u5E74\u5EA6\u7EF4\u62A4\u670D\u52A1\uFF0C\u60A8\u5DF2\u7ECF\u5B8C\u6210\u5B58\u50A8\u7684\u6062\u590D\u5730\u56FE\u4ECD\u7136\u4F1A\u957F\u671F\u5B58\u50A8\uFF0C\u4E0D\u53D7\u5F71\u54CD\u3002</strong></p><p><strong>\u60A8\u4ECD\u7136\u53EF\u4EE5\u4F7F\u7528\u81EA\u5DF1\u4FDD\u5B58\u7684\u6062\u590D\u5BC6\u94A5\u51ED\u8BC1\u548C\u6062\u590D\u5BC6\u7801\uFF0C\u72EC\u7ACB\u6062\u590D\u5B8C\u6574\u7684\u6062\u590D\u5730\u56FE\u3002</strong></p><p>\u7B2C\u4E8C\u5E74\u5E74\u5EA6\u7EF4\u62A4\u670D\u52A1\u63D0\u4F9B\u6062\u590D\u5730\u56FE\u5185\u5BB9\u66F4\u65B0\u3001\u6062\u590D\u6F14\u7EC3\u3001\u4E13\u5C5E\u4EBA\u5DE5\u670D\u52A1\u548C\u6301\u7EED\u5BA2\u6237\u652F\u6301\u3002</p><p>\u5982\u679C\u8D26\u6237\u3001\u8BBE\u5907\u3001\u6062\u590D\u6761\u4EF6\u3001\u5BB6\u5EAD\u5B89\u6392\u6216\u6062\u590D\u5730\u56FE\u4E2D\u7684\u91CD\u8981\u4FE1\u606F\u53D1\u751F\u53D8\u5316\uFF0C\u5EFA\u8BAE\u7EE7\u7EED\u4F7F\u7528\u7B2C\u4E8C\u5E74\u5E74\u5EA6\u7EF4\u62A4\u670D\u52A1\uFF0C\u8BA9\u4FE1\u606F\u53CA\u65F6\u66F4\u65B0\u3002</p><p>\u5E74\u5EA6\u7EF4\u62A4\u7684\u4EF7\u503C\uFF0C\u662F\u8BA9\u5DF2\u7ECF\u5EFA\u7ACB\u597D\u7684\u6062\u590D\u4F53\u7CFB\u4E0D\u4EC5\u80FD\u591F\u957F\u671F\u5B58\u50A8\uFF0C\u4E5F\u80FD\u6301\u7EED\u8DDF\u5F97\u4E0A\u60A8\u7684\u771F\u5B9E\u60C5\u51B5\u3002</p></div></details>${[{q:"\u5982\u679C\u53EA\u9700\u8981\u4E34\u65F6\u66F4\u65B0\u4E00\u6B21\uFF0C\u600E\u4E48\u529E\uFF1F",a:[`\u5355\u6B21\u6062\u590D\u5730\u56FE\u5185\u5BB9\u66F4\u65B0\uFF1A${t} ${t==="USD"?"199":"280"} / \u6B21\u3002`,"\u94B1\u5305\u3001\u8D26\u6237\u3001\u8BBE\u5907\u6216\u6062\u590D\u4FE1\u606F\u53D1\u751F\u53D8\u5316\u65F6\uFF0C\u53EF\u4EE5\u5355\u72EC\u8D2D\u4E70\u4E00\u6B21\u6062\u590D\u5730\u56FE\u5185\u5BB9\u66F4\u65B0\u3002","\u5982\u679C\u9884\u8BA1\u672A\u6765\u4E00\u5E74\u8FD8\u4F1A\u7EE7\u7EED\u53D1\u751F\u53D8\u5316\uFF0C\u7B2C\u4E8C\u5E74\u5E74\u5EA6\u7EF4\u62A4\u670D\u52A1\u901A\u5E38\u66F4\u5408\u9002\u3002"]},{q:"\u4EE5\u540E\u53EF\u4EE5\u5347\u7EA7\u5230\u66F4\u9AD8\u4E00\u7EA7\u670D\u52A1\u5417\uFF1F",a:["\u53EF\u4EE5\u3002",`\u4F8B\u5982\u4ECE\u57FA\u7840\u7248\u5E74\u5EA6\u7EF4\u62A4\u670D\u52A1\u5347\u7EA7\u81F3\u6807\u51C6\u7248\u5E74\u5EA6\u7EF4\u62A4\u670D\u52A1\uFF1A\u4E00\u6B21\u6027\u5347\u7EA7\u8D39\u7528 ${t} ${t==="USD"?"599":"840"}\uFF0C\u5E76\u8865\u8DB3\u5F53\u524D\u5E74\u5EA6\u4E24\u4E2A\u670D\u52A1\u4E4B\u95F4\u7684\u8D39\u7528\u5DEE\u989D\u3002`,"\u5DF2\u7ECF\u652F\u4ED8\u7684\u5F53\u524D\u5E74\u5EA6\u670D\u52A1\u8D39\u7528\u4E0D\u4F1A\u91CD\u590D\u6536\u53D6\u3002"]}].map(p=>`<details><summary>${h(p.q)}</summary><div>${i(p.a)}</div></details>`).join("")}</div></section>
